const request = $json.body ?? $json;

const email = String(request.email ?? "").trim();
const reviewText = String(request.reviewText ?? "").trim();
const reviewedUrl = String(request.reviewedUrl ?? "").trim();
const fileName = String(request.fileName ?? "code-review").trim();

if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error("A valid recipient email address is required.");
}

if (!reviewText) {
  throw new Error("Review content is required.");
}

if (!reviewedUrl) {
  throw new Error("Reviewed GitHub URL is required.");
}

return [
  {
    json: {
      email,
      reviewText,
      reviewedUrl,
      fileName,
      generatedAt: new Date().toISOString()
    }
  }
];

const {
  email,
  reviewText,
  reviewedUrl,
  fileName,
  generatedAt
} = $json;

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

const htmlBody = `
<!doctype html>
<html>
<body style="font-family: Arial, sans-serif; color: #1f2328; line-height: 1.5;">
  <h2 style="color: #0969da;">AI Tester CodeLens</h2>

  <p><strong>GitHub Code Review</strong></p>

  <p>
    <strong>File:</strong> ${escapeHtml(fileName)}<br>
    <strong>Reviewed URL:</strong>
    <a href="${escapeHtml(reviewedUrl)}">${escapeHtml(reviewedUrl)}</a><br>
    <strong>Generated:</strong> ${escapeHtml(generatedAt)}
  </p>

  <hr>

  <div style="white-space: pre-wrap; font-family: Arial, sans-serif;">
    ${escapeHtml(reviewText)}
  </div>
</body>
</html>
`;

const textBody = `
AI Tester CodeLens
GitHub Code Review

File: ${fileName}
Reviewed URL: ${reviewedUrl}
Generated: ${generatedAt}

----------------------------------------

${reviewText}
`;

return [
  {
    json: {
      email,
      fileName,
      reviewedUrl,
      generatedAt,
      htmlBody,
      textBody
    }
  }
];
